import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"AI-Driven Intelligent Business Intelligence and Control Platform | SyncInsight","description":"A next-generation data control platform that collects, analyzes, and visualizes data across the SyncSeries ecosystem, deriving business insights based on AI inference.","frontmatter":{"title":"AI-Driven Intelligent Business Intelligence and Control Platform | SyncInsight","description":"A next-generation data control platform that collects, analyzes, and visualizes data across the SyncSeries ecosystem, deriving business insights based on AI inference.","head":[["meta",{"name":"keywords","content":"SyncInsight, Business Intelligence, Data Visualization, AI Control Platform, Data Analysis, Dashboard, Agent Monitoring, AIOps, Real-time Data, Empasy, Insight Generation"}],["meta",{"property":"og:title","content":"AI-Driven Intelligent Business Intelligence and Control Platform | SyncInsight"}],["meta",{"property":"og:description","content":"A next-generation control platform that collects scattered data to derive business insights based on AI inference."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/syncinsight/"}]],"order":1,"dir":{"order":6}},"headers":[],"relativePath":"en/syncinsight/index.md","filePath":"en/syncinsight/index.md","lastUpdated":1784589221000}`),a={name:`en/syncinsight/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="syncinsight-ai-driven-intelligent-data-control-center" tabindex="-1">SyncInsight: AI-Driven Intelligent Data Control Center <a class="header-anchor" href="#syncinsight-ai-driven-intelligent-data-control-center" aria-label="Permalink to “SyncInsight: AI-Driven Intelligent Data Control Center”">​</a></h1><p>SyncInsight is a next-generation Business Intelligence (BI) and control platform that integrates vast amounts of data scattered inside and outside the system, allowing AI to analyze and visualize it.</p><p>Without the need for administrators to write complex queries to extract data, it aggregates all activity logs and business data generated from the agent ecosystem (SyncVerse, SyncBoot, SyncCrawl, etc.), while AI autonomously discovers meaningful metrics and presents them in an intuitive dashboard format.</p><hr><h2 id="_1-core-capabilities-of-intelligent-data-analysis" tabindex="-1">1. Core Capabilities of Intelligent Data Analysis <a class="header-anchor" href="#_1-core-capabilities-of-intelligent-data-analysis" aria-label="Permalink to “1. Core Capabilities of Intelligent Data Analysis”">​</a></h2><p>Going beyond simply showing statistics, it embeds an AI analysis layer that grasps the meaning behind the data.</p><ul><li><strong>Real-Time Data Streaming Analysis</strong>: It instantly analyzes incoming traffic, user behavior, and system status logs in real-time, visualizing the current situation rather than static historical data.</li><li><strong>Anomaly Detection</strong>: Beyond simple alarms exceeding set thresholds, AI proactively detects subtle abnormal system signs or traffic spikes that differ from normal patterns and reports potential causes.</li><li><strong>Natural Language Query (NLQ) Support</strong>: Without complex dashboard configuration or SQL knowledge, by asking everyday questions like &quot;What caused the page with the highest increase in visitors last week?&quot;, AI extracts the relevant data and constructs a chart to answer.</li></ul><h2 id="_2-organic-integrated-monitoring-with-the-sync-ecosystem" tabindex="-1">2. Organic Integrated Monitoring with the Sync Ecosystem <a class="header-anchor" href="#_2-organic-integrated-monitoring-with-the-sync-ecosystem" aria-label="Permalink to “2. Organic Integrated Monitoring with the Sync Ecosystem”">​</a></h2><p>It provides enterprise-wide insights by integrating metadata generated by various agents of the SyncSeries.</p><ul><li><strong>SyncVerse Agent Activity Tracking</strong>: Transparently visualizes the task history, decision paths, and Agent-to-Agent (A2A) communication flows of each AI agent, allowing monitoring and control of the AI&#39;s autonomous operation processes.</li><li><strong>SyncCrawl Collected Data Visualization</strong>: AI analyzes unstructured text data collected from the outside by crawler agents, converting market trends, sentiment analysis results, etc., into intuitive graphs.</li><li><strong>SyncETA Test Quality Dashboard</strong>: Predicts the stability of software releases by analyzing quality metrics such as pass/fail ratios of automated tests and error occurrence frequencies.</li></ul><h2 id="_3-flexible-dashboard-environment-and-decision-support" tabindex="-1">3. Flexible Dashboard Environment and Decision Support <a class="header-anchor" href="#_3-flexible-dashboard-environment-and-decision-support" aria-label="Permalink to “3. Flexible Dashboard Environment and Decision Support”">​</a></h2><p>It provides a flexible environment so various members of a company can view data appropriate for their roles.</p><ul><li><strong>Drag-and-Drop Customization</strong>: Supports a personalized dashboard configuration feature where you can freely place and save necessary metrics and charts on the screen.</li><li><strong>AI-Based Action Proposals</strong>: When a problem occurs, it doesn&#39;t just issue a warning; based on the data, it proposes the next course of action to the administrator, such as &quot;Should I add a server instance?&quot; or &quot;Should I activate the blocking policy?&quot;</li><li><strong>Role-Based Access Control (RBAC)</strong>: Automatically adjusts the depth and scope of data that can be viewed according to the permissions of titles and departments, maintaining information security.</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};